//! Exact public synthetic records generated by the released schema15 binary.
//! The fixture contains public credentials/assertions and consumed ceremony
//! state, never fixture signing seeds or authenticator private keys.
use super::*;
use base64::{Engine, engine::general_purpose::STANDARD};
use serde::Deserialize;
use std::collections::BTreeSet;

const FIXTURE_BYTES: &[u8] =
    include_bytes!("../../tests/fixtures/authority-v15-owner-bootstrap.json");
const FIXTURE_SHA: &str = "sha256:68754c509071e2a175b6207a9e00e2c65b91877e62d72a28ea3433a44b67db1e";
const ALIAS_FIXTURE_BYTES: &[u8] =
    include_bytes!("../../tests/fixtures/authority-v15-cross-purpose-alias.json");
const ALIAS_FIXTURE_SHA: &str =
    "sha256:4e193a7d80ea7aad6f262506abfe58796944119dbdcb2de9bb6f777df3c7407d";
const ORIGIN: &str = "http://localhost:8787";

#[derive(Deserialize)]
#[serde(deny_unknown_fields)]
struct LegacyFixture {
    schema_version: String,
    application_id: i64,
    user_version: i64,
    fixture_time: i64,
    authorization_hash: String,
    #[serde(default)]
    old15_cross_role_transport_pin_accepted: bool,
    #[serde(default)]
    original_healthy_fixture_sha256: Option<String>,
    normal_public_flow: Value,
    provenance: Value,
    tables: Vec<LegacyTable>,
}
#[derive(Deserialize)]
#[serde(deny_unknown_fields)]
struct LegacyTable {
    name: String,
    columns: Vec<String>,
    rows: Vec<Vec<LegacyCell>>,
}
#[derive(Deserialize)]
#[serde(tag = "type", rename_all = "lowercase", deny_unknown_fields)]
enum LegacyCell {
    Null,
    Integer { value: i64 },
    Text { value: String },
    Blob { base64: String },
}
impl LegacyCell {
    fn sql(&self) -> rusqlite::types::Value {
        use rusqlite::types::Value as Sql;
        match self {
            Self::Null => Sql::Null,
            Self::Integer { value } => Sql::Integer(*value),
            Self::Text { value } => Sql::Text(value.clone()),
            Self::Blob { base64 } => {
                let bytes = STANDARD.decode(base64).unwrap();
                assert_eq!(STANDARD.encode(&bytes), *base64);
                Sql::Blob(bytes)
            }
        }
    }
}

fn fixture() -> LegacyFixture {
    assert_eq!(hash_bytes(FIXTURE_BYTES), FIXTURE_SHA);
    let fixture: LegacyFixture = serde_json::from_slice(FIXTURE_BYTES).unwrap();
    assert_eq!(
        fixture.schema_version,
        "fw.synthetic-authority-v15-fixture/v1"
    );
    assert_eq!(fixture.application_id, APPLICATION_ID);
    assert_eq!(fixture.user_version, 15);
    assert!(!fixture.old15_cross_role_transport_pin_accepted);
    assert!(fixture.original_healthy_fixture_sha256.is_none());
    assert_eq!(
        fixture.provenance["source_commit"],
        "5fc576f672c2e0671164b73a667e3452b99ea82a"
    );
    assert_eq!(
        fixture.provenance["source_tree"],
        "719b80f88255921711ede7b4f4da81876568f7e3"
    );
    assert_eq!(fixture.normal_public_flow["operator_commands"], 17);
    for key in [
        "owner_proof_created",
        "bootstrap_signature_verified",
        "released_store_full_validation",
    ] {
        assert_eq!(fixture.normal_public_flow[key], true);
    }
    for name in [
        "fw_authority_admin",
        "fw_signer",
        "examples/protected_signer_fixture",
    ] {
        let hash = fixture.provenance["binaries"][name].as_str().unwrap();
        assert!(
            hash.len() == 64
                && hash
                    .bytes()
                    .all(|byte| byte.is_ascii_digit() || (b'a'..=b'f').contains(&byte))
        );
    }
    fixture
}

fn alias_fixture() -> LegacyFixture {
    assert_eq!(hash_bytes(ALIAS_FIXTURE_BYTES), ALIAS_FIXTURE_SHA);
    let fixture: LegacyFixture = serde_json::from_slice(ALIAS_FIXTURE_BYTES).unwrap();
    assert_eq!(
        fixture.schema_version,
        "fw.synthetic-authority-v15-fixture/v1"
    );
    assert_eq!(fixture.application_id, APPLICATION_ID);
    assert_eq!(fixture.user_version, 15);
    assert!(fixture.old15_cross_role_transport_pin_accepted);
    assert_eq!(
        fixture.original_healthy_fixture_sha256.as_deref(),
        Some(FIXTURE_SHA)
    );
    assert_eq!(
        fixture.provenance["source_commit"],
        "5fc576f672c2e0671164b73a667e3452b99ea82a"
    );
    assert_eq!(
        fixture.provenance["source_tree"],
        "719b80f88255921711ede7b4f4da81876568f7e3"
    );
    assert_eq!(
        fixture.provenance["binaries"]["fw_authority_admin"],
        "a734447942289b40c411185ec160b7c0bdaaee670ac87d4ddca09e5990d68258"
    );
    for name in [
        "old15_pre_pin_full_validation",
        "old15_post_pin_full_validation",
        "old15_cross_role_transport_pin_accepted",
    ] {
        assert_eq!(fixture.normal_public_flow[name], true);
    }
    assert_eq!(
        fixture.normal_public_flow["actual_additional_admin_commands"],
        4
    );
    assert_eq!(fixture.normal_public_flow["signer_process_started"], false);
    assert_eq!(
        fixture.normal_public_flow["private_key_material_transferred"],
        false
    );
    fixture
}

fn table_names(connection: &Connection) -> Vec<String> {
    connection.prepare("SELECT name FROM sqlite_schema WHERE type='table' AND substr(name,1,10)='authority_' ORDER BY name").unwrap().query_map([],|row|row.get(0)).unwrap().collect::<rusqlite::Result<Vec<_>>>().unwrap()
}

fn legacy_database(path: &Path, fixture: &LegacyFixture) {
    let mut options = fs::OpenOptions::new();
    options.write(true).create_new(true);
    #[cfg(unix)]
    {
        use std::os::unix::fs::OpenOptionsExt;
        options.mode(0o600);
    }
    // Close this non-SQLite descriptor before SQLite opens the same inode.
    drop(options.open(path).unwrap());
    let mut connection = Connection::open(path).unwrap();
    let journal: String = connection
        .query_row("PRAGMA journal_mode=WAL", [], |row| row.get(0))
        .unwrap();
    assert_eq!(journal, "wal");
    connection
        .pragma_update(None, "synchronous", "FULL")
        .unwrap();
    connection
        .pragma_update(None, "foreign_keys", "OFF")
        .unwrap();
    let tx = connection.transaction().unwrap();
    initialize_v1(&tx).unwrap();
    apply_v2(&tx).unwrap();
    apply_v3(&tx).unwrap();
    apply_v4(&tx).unwrap();
    apply_v5(&tx).unwrap();
    apply_v6(&tx).unwrap();
    apply_v7(&tx).unwrap();
    apply_v8(&tx).unwrap();
    apply_v9(&tx).unwrap();
    apply_v10(&tx).unwrap();
    apply_v11(&tx).unwrap();
    apply_v12(&tx).unwrap();
    apply_v13(&tx).unwrap();
    apply_v14(&tx).unwrap();
    apply_v15(&tx).unwrap();
    let guards = known_v15().unwrap().guards.clone();
    for (name, _) in &guards {
        tx.execute_batch(&format!("DROP TRIGGER {name}")).unwrap();
    }
    let tables = table_names(&tx);
    for table in &tables {
        tx.execute(&format!("DELETE FROM {table}"), []).unwrap();
    }
    let mut loaded = BTreeSet::new();
    for table in &fixture.tables {
        assert!(tables.contains(&table.name) && loaded.insert(table.name.clone()));
        let columns = tx
            .prepare(&format!("PRAGMA table_info({})", table.name))
            .unwrap()
            .query_map([], |row| row.get::<_, String>(1))
            .unwrap()
            .collect::<rusqlite::Result<Vec<_>>>()
            .unwrap();
        assert_eq!(table.columns.len(), columns.len() + 1);
        assert_eq!(&table.columns[1..], columns);
        // SQLite labels rowid with the INTEGER PRIMARY KEY's alias for two
        // tables. Its first projected value is still the hidden row identity;
        // normalize only this in-memory insert label, never fixture bytes.
        assert!(
            table.columns[0] == "rowid"
                || table.columns[0] == "singleton"
                || table.columns[0] == "version"
        );
        let names = std::iter::once("rowid")
            .chain(columns.iter().map(String::as_str))
            .collect::<Vec<_>>()
            .join(",");
        let placeholders = (1..=columns.len() + 1)
            .map(|column| format!("?{column}"))
            .collect::<Vec<_>>()
            .join(",");
        let sql = format!("INSERT INTO {}({names}) VALUES({placeholders})", table.name);
        for row in &table.rows {
            assert_eq!(row.len(), columns.len() + 1);
            assert!(matches!(row[0], LegacyCell::Integer { .. }));
            tx.execute(
                &sql,
                rusqlite::params_from_iter(row.iter().map(LegacyCell::sql)),
            )
            .unwrap();
        }
    }
    for (_, sql) in guards {
        tx.execute_batch(&sql).unwrap();
    }
    assert_eq!(schema_digest(&tx).unwrap(), known_v15().unwrap().digest);
    validate_v15(&tx).unwrap();
    tx.commit().unwrap();
    connection
        .pragma_update(None, "foreign_keys", "ON")
        .unwrap();
}

type Snapshot = Vec<(String, Vec<Vec<rusqlite::types::Value>>)>;
fn snapshot(path: &Path) -> Snapshot {
    let connection = Connection::open(path).unwrap();
    table_names(&connection)
        .into_iter()
        .map(|table| {
            let mut query = connection
                .prepare(&format!("SELECT rowid,* FROM {table} ORDER BY rowid"))
                .unwrap();
            let columns = query.column_count();
            let rows = query
                .query_map([], |row| {
                    (0..columns)
                        .map(|column| row.get(column))
                        .collect::<rusqlite::Result<Vec<_>>>()
                })
                .unwrap()
                .collect::<rusqlite::Result<Vec<_>>>()
                .unwrap();
            (table, rows)
        })
        .collect()
}
fn preserved(after: &Snapshot, before: &Snapshot) {
    for (table, rows) in before {
        let actual = &after.iter().find(|(name, _)| name == table).unwrap().1;
        if table == "authority_schema_migrations" {
            assert!(actual.starts_with(rows));
            assert_eq!(actual.len(), 16);
        } else {
            assert_eq!(actual, rows, "{table}: original rowids/types/bytes");
        }
    }
}

#[test]
fn released_v15_owner_history_is_preserved_but_never_becomes_a_pinned_origin() {
    let fixture = fixture();
    let directory = super::super::signing_test_support::private_directory::private_directory();
    let path = directory.path().join("released15.sqlite3");
    legacy_database(&path, &fixture);
    let before = snapshot(&path);
    assert!(matches!(
        AuthorityStore::open(&path),
        Err(AuthorityError::MigrationRequired {
            found: 15,
            required: 16
        })
    ));
    let backup = directory.path().join("released15-backup.sqlite3");
    AuthorityStore::migrate(&path, &backup).unwrap();
    assert_eq!(snapshot(&backup), before);
    preserved(&snapshot(&path), &before);
    let db = Connection::open(&path).unwrap();
    let (org, project): (String, String) = db
        .query_row(
            "SELECT org_id,project_id FROM authority_bootstrap_proofs",
            [],
            |row| Ok((row.get(0)?, row.get(1)?)),
        )
        .unwrap();
    let tenant = AuthorityTenant::new(&org, &project).unwrap();
    let (manifest_id,canonical):(String,Vec<u8>)=db.query_row("SELECT object_id,canonical_bytes FROM authority_registry_objects WHERE object_kind='bootstrap_authorization'",[],|row|Ok((row.get(0)?,row.get(1)?))).unwrap();
    let original: crate::BootstrapAuthorization = decode(&canonical).unwrap();
    assert_eq!(hash_bytes(&canonical), fixture.authorization_hash);
    let manifest_bytes: Vec<u8> = db
        .query_row(
            "SELECT canonical_bytes FROM authority_registry_objects WHERE object_kind='bootstrap_manifest' AND object_id=?",
            [&manifest_id],
            |row| row.get(0),
        )
        .unwrap();
    let manifest: crate::AuthorityBootstrapManifest = decode(&manifest_bytes).unwrap();
    // The fixture timestamp starts the real multi-process ceremony. Its later
    // CLI/signature/health reads advanced the durable clock; never lower it.
    let floor: i64 = db
        .query_row(
            "SELECT max(observed_at) FROM (SELECT observed_at FROM authority_registry_clocks WHERE org_id=?1 AND project_id=?2 UNION ALL SELECT observed_at FROM authority_target_clocks WHERE org_id=?1 AND project_id=?2)",
            params![tenant.org_id, tenant.project_id],
            |row| row.get(0),
        )
        .unwrap();
    let now = floor.checked_add(1).unwrap();
    assert!(now > fixture.fixture_time);
    assert!(now < crate::timestamp(&manifest.expires_at).unwrap());
    assert!(now < crate::timestamp(&original.payload.not_after).unwrap());
    let proof_deadline: i64 = db
        .query_row(
            "SELECT min(expires_at) FROM authority_bootstrap_proofs WHERE org_id=? AND project_id=? AND manifest_id=?",
            params![tenant.org_id, tenant.project_id, manifest_id],
            |row| row.get(0),
        )
        .unwrap();
    assert!(now < proof_deadline, "legacy proof must still be live");
    let challenges: i64 = db
        .query_row(
            "SELECT count(*) FROM authority_bootstrap_challenges",
            [],
            |row| row.get(0),
        )
        .unwrap();
    assert!(challenges > 0);
    assert_eq!(db.query_row("SELECT count(*) FROM authority_bootstrap_challenge_origin_bindings WHERE origin_revision IS NULL",[],|row|row.get::<_,i64>(0)).unwrap(),challenges);
    assert_eq!(db.query_row("SELECT count(*) FROM authority_bootstrap_challenge_origin_bindings WHERE origin_revision IS NOT NULL",[],|row|row.get::<_,i64>(0)).unwrap(),0);
    for table in [
        "authority_bootstrap_approval_origin_pins",
        "authority_bootstrap_approval_origin_heads",
        "authority_target_bootstrap_key_pins",
        "authority_target_bootstrap_key_heads",
        "authority_target_bootstrap_key_revocations",
        "authority_target_bootstrap_challenges",
        "authority_target_bootstrap_confirmations",
        "authority_target_bootstrap_confirmation_heads",
    ] {
        assert_eq!(
            db.query_row(&format!("SELECT count(*) FROM {table}"), [], |row| row
                .get::<_, i64>(0))
                .unwrap(),
            0
        );
    }
    drop(db);
    let mut store = AuthorityStore::open(&path).unwrap();
    assert!(
        store
            .read_bootstrap_approval_origin(&tenant, now)
            .unwrap()
            .is_none()
    );
    assert_eq!(
        store
            .read_registry_object(&tenant, "bootstrap_manifest", &manifest_id, now)
            .unwrap()
            .unwrap()
            .state,
        "staged"
    );
    assert_eq!(
        store
            .read_registry_object(&tenant, "bootstrap_authorization", &manifest_id, now)
            .unwrap()
            .unwrap()
            .state,
        "historical"
    );
    let verifier = WebAuthn::new(ORIGIN).unwrap();
    let pin = crate::BootstrapApprovalOriginPin {
        schema_version: "fw.bootstrap-approval-origin-pin/v1".into(),
        org_id: org,
        project_id: project,
        revision: "1".into(),
        origin: ORIGIN.into(),
        rp_id: verifier.rp_id().into(),
        not_before: at(fixture.fixture_time - 60).unwrap(),
        not_after: at(fixture.fixture_time + 3600).unwrap(),
    };
    store
        .pin_bootstrap_approval_origin(&tenant, &pin, None, now)
        .unwrap();
    assert_eq!(
        store
            .read_registry_object(&tenant, "bootstrap_manifest", &manifest_id, now)
            .unwrap()
            .unwrap()
            .state,
        "staged"
    );
    let retry = store
        .admit_bootstrap_authorization(&tenant, &manifest_id, &original, &verifier, now)
        .unwrap();
    assert_eq!(retry.state, "historical");
    assert!(!retry.current && !retry.signing_allowed && !retry.dispatch_allowed);
    let db = Connection::open(&path).unwrap();
    let bytes:Vec<u8>=db.query_row("SELECT canonical_bytes FROM authority_registry_objects WHERE object_kind='bootstrap_authorization'",[],|row|row.get(0)).unwrap();
    assert_eq!(bytes, canonical);
    assert_eq!(db.query_row("SELECT count(*) FROM authority_bootstrap_challenge_origin_bindings WHERE origin_revision IS NULL",[],|row|row.get::<_,i64>(0)).unwrap(),challenges);
    drop(db);
    drop(store);
    AuthorityStore::open(&path).unwrap();
}

#[test]
fn released_v15_history_and_private_backup_survive_every_late_schema16_failure() {
    let fixture = fixture();
    for stage in [
        "schema16-authority-created",
        "schema16-version-recorded",
        "before-commit",
    ] {
        let directory = super::super::signing_test_support::private_directory::private_directory();
        let path = directory.path().join("released15.sqlite3");
        legacy_database(&path, &fixture);
        let before = snapshot(&path);
        let schema = schema_digest(&Connection::open(&path).unwrap()).unwrap();
        let backup = directory.path().join("failed-upgrade-backup.sqlite3");
        MIGRATION_FAILURE.with(|requested| *requested.borrow_mut() = Some(stage));
        let result = AuthorityStore::migrate(&path, &backup);
        MIGRATION_FAILURE.with(|requested| *requested.borrow_mut() = None);
        assert!(
            matches!(
                result,
                Err(AuthorityError::Invalid(
                    "injected authority migration failure"
                ))
            ),
            "{stage}"
        );
        assert_eq!(snapshot(&path), before);
        assert_eq!(snapshot(&backup), before);
        assert_eq!(
            schema_digest(&Connection::open(&path).unwrap()).unwrap(),
            schema
        );
        assert_eq!(
            Connection::open(&path)
                .unwrap()
                .query_row("PRAGMA user_version", [], |row| row.get::<_, i64>(0))
                .unwrap(),
            15
        );
        #[cfg(unix)]
        {
            use std::os::unix::fs::PermissionsExt;
            for file in [&backup, &backup.with_extension("manifest.json")] {
                assert_eq!(
                    fs::metadata(file).unwrap().permissions().mode() & 0o777,
                    0o600
                );
            }
        }
    }
}

#[test]
fn released_v15_cross_purpose_alias_refuses_upgrade_without_changing_history() {
    let fixture = alias_fixture();
    let directory = super::super::signing_test_support::private_directory::private_directory();
    let path = directory.path().join("released15-alias.sqlite3");
    legacy_database(&path, &fixture);
    let before = snapshot(&path);
    let original_bytes = fs::read(&path).unwrap();
    let connection = Connection::open(&path).unwrap();
    let alias: bool = connection
        .query_row(
            "SELECT EXISTS(SELECT 1 FROM authority_registry_keys r JOIN authority_target_keys t ON t.org_id=r.org_id AND t.public_key=r.public_key WHERE t.key_fingerprint!=r.key_fingerprint)",
            [],
            |row| row.get(0),
        )
        .unwrap();
    assert!(
        alias,
        "released API retained a raw/SPKI cross-purpose alias"
    );
    let schema = schema_digest(&connection).unwrap();
    drop(connection);
    assert!(matches!(
        AuthorityStore::open(&path),
        Err(AuthorityError::MigrationRequired {
            found: 15,
            required: 16
        })
    ));
    let backup = directory.path().join("quarantined15-backup.sqlite3");
    assert!(matches!(
        AuthorityStore::migrate(&path, &backup),
        Err(AuthorityError::Invalid("authority key purpose alias"))
    ));
    assert_eq!(snapshot(&path), before);
    assert_eq!(snapshot(&backup), before);
    assert_eq!(fs::read(&path).unwrap(), original_bytes);
    let backup_manifest: Value =
        serde_json::from_slice(&fs::read(backup.with_extension("manifest.json")).unwrap()).unwrap();
    assert_eq!(backup_manifest["database_schema"], 15);
    assert_eq!(
        backup_manifest["database_hash"],
        hash_bytes(&fs::read(&backup).unwrap())
    );
    let connection = Connection::open(&path).unwrap();
    assert_eq!(schema_digest(&connection).unwrap(), schema);
    assert_eq!(
        connection
            .query_row("PRAGMA user_version", [], |row| row.get::<_, i64>(0))
            .unwrap(),
        15
    );
    drop(connection);
    assert!(matches!(
        AuthorityStore::open(&path),
        Err(AuthorityError::MigrationRequired {
            found: 15,
            required: 16
        })
    ));
    #[cfg(unix)]
    {
        use std::os::unix::fs::PermissionsExt;
        for file in [&backup, &backup.with_extension("manifest.json")] {
            assert_eq!(
                fs::metadata(file).unwrap().permissions().mode() & 0o777,
                0o600
            );
        }
    }
}
